<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserGroupMembershipUserAccessor
{
    private UserGroupMembershipUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserGroupMembershipUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserGroupMembershipUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserGroupMembershipUserVO::from($user);
        return $copy;
    }
}
